style.css:
@-moz-document domain("webapp.ame.nu") {
.container {
    max-width: 100%;
}
.container > .row > .col {
    display: none;
}
.col-lg-4 {
    flex: 0 0 25%;
    max-width: 25%;
}
.col-lg-8 {
    flex: 0 0 75%;
    max-width: 75%;
}
.col-sm-12 {
    display: none;
}
.py-5 {
    padding-top: 0 !important;
}
.wbso_slider_wrapper {
    display: none;
}
.slider .btn {
    display: none;
}
.slider {
    margin-bottom: 10px !important;
    display: inline-block;
    max-width: 25%;
    min-width: 25%;
}
.action_wrapper {
    padding: 0 !important;
}
}
